#!/usr/bin/env bash
#
# PinPals — the rest of the app goes native.
#
#   bash apply-app-native-complete.sh
#
# SUPERSEDES every earlier script in this run. Run only this one.
#
# New here, on top of the last bundle:
#   * mobile/src/app/my-rounds.tsx  — Rounds I've posted, with host actions
#   * mobile/src/app/buying.tsx     — purchases, offers & bids, saved, reviews
#   * mobile/src/app/order/[id].tsx — one order, from either side
#   * src/app/api/app/tee-times/invites/[id]/route.ts — PATCH and DELETE
#
# WHY CANCELLING A ROUND IS A ROUTE AND NOT A TABLE WRITE. The app could
# update the status column itself; the "Update own invites" policy (0028)
# allows it. What it could not do is tell anyone. Cancelling notifies every
# member who asked, was offered a place, or confirmed one, and that notice is
# assembled server-side with the admin client. A round called off silently is
# somebody driving to a tee time that isn't happening. The work moved into
# src/lib/tee-times-operations.ts, beside the three writes already there, so
# the website's Server Action and the app's route run the same sequence.
#
# The menu loses its "Dashboard" row: it pointed at a website page that
# repeats, less well, what the Home tab already shows. "Buying" and "Orders"
# became one row for the same reason — purchases ARE the orders, and two rows
# to one screen is a menu asking you to guess.
set -euo pipefail

say() { printf '\n\033[1m%s\033[0m\n' "$*"; }
die() { printf '\n\033[31mSTOPPED: %s\033[0m\n' "$*" >&2; exit 1; }

[ -f mobile/app.json ] && [ -d supabase/migrations ] \
  || die "run this from the repo root — the folder that has mobile/ and supabase/ in it"
[ -f mobile/src/components/screen-header.tsx ] \
  || die "the photo headers are missing from this checkout. Pull main first: git pull origin main"
[ -e mobile/src/app/buying.tsx ] \
  && die "mobile/src/app/buying.tsx already exists — this has been applied already"

say "Unpacking…"
TMP=$(mktemp -d); trap 'rm -rf "$TMP"' EXIT
base64 -d > "$TMP/p.tgz" <<'PAYLOAD'
